// Pega o CSV como texto vindo do HTTP Request

const csvRaw = $json.data ?? $json.body ?? $json;
const text = typeof csvRaw === "string"
  ? csvRaw
  : JSON.stringify(csvRaw);

const lines = text
  .split(/\r?\n/)
  .map(l => l.trim())
  .filter(Boolean);

const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};

  headers.forEach((h, i) => {
    obj[h] = cols[i] ?? "";
  });

  // Normaliza o campo minimo para número
  obj.minimo =
    Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

const entrada = $input.first().json;

// 1. Recupera clientes e investimentos
const body = entrada.body ?? entrada;

const clientes = body.clientes ?? entrada.clientes ?? [];
const investimentos =
  entrada.investimentos ?? body.investimentos ?? [];

// 2. Converte saldo brasileiro para número
function converterSaldo(valor) {
  if (typeof valor === "number") return valor;

  const normalizado = String(valor ?? "")
    .replace(/[^\d,.-]/g, "")
    .replace(/\./g, "")
    .replace(",", ".");

  const numero = Number(normalizado);

  return Number.isFinite(numero) ? numero : 0;
}

// 3. Processa cada cliente
const resultados = clientes.map(cliente => {
  const perfil = String(cliente.perfil ?? "").trim();
  const saldoNum = converterSaldo(cliente.saldo);

  // 4. Filtra investimentos do mesmo perfil
  // cujo valor mínimo seja compatível com o saldo
  const elegiveis = investimentos.filter(inv => {
    return (
      String(inv.perfil ?? "").trim().toLowerCase() ===
        perfil.toLowerCase() &&
      Number(inv.minimo) <= saldoNum
    );
  });

  // 5. Seleciona o investimento com o maior mínimo elegível
  elegiveis.sort((a, b) =>
    Number(b.minimo) - Number(a.minimo)
  );

  const investimento = elegiveis[0] ?? null;

  // 6. Define o motivo
  const motivo = investimento
    ? "saldo_ok"
    : "saldo_incompatível";

  // 7. Prepara os dados da recomendação
  const nome = String(cliente.nome ?? "").trim() || "cliente";

  const minimoFormatado = investimento
    ? Number(investimento.minimo).toLocaleString("pt-BR", {
        style: "currency",
        currency: "BRL"
      })
    : null;

  const produto = investimento?.produto ?? null;
  const rentabilidade = investimento?.rentabilidade ?? null;

  // 8. Gera três mensagens
  const mensagens = [
    `Olá, ${nome}! Considerando seu perfil ${perfil}, ` +
    (investimento
      ? `identificamos o produto ${produto}, com aplicação mínima ` +
        `de ${minimoFormatado} e rentabilidade informada de ` +
        `${rentabilidade}. Podemos conversar sobre suas características e riscos?`
      : `não encontramos um investimento compatível com seu saldo. ` +
        `Podemos avaliar outras alternativas?`),

    `Oi, ${nome}! Analisamos as opções para seu perfil ${perfil}. ` +
    (investimento
      ? `O ${produto} possui aplicação mínima de ${minimoFormatado} ` +
        `e rentabilidade informada de ${rentabilidade}. ` +
        `Vale avaliar os riscos e as condições antes de decidir.`
      : `não identificamos uma opção com aplicação mínima compatível ` +
        `com seu saldo. Podemos buscar alternativas?`),

    `Sr./Sra. ${nome}, conforme o perfil ${perfil} informado, ` +
    (investimento
      ? `o ${produto} atende ao critério de saldo mínimo, ` +
        `com aplicação inicial de ${minimoFormatado} e rentabilidade ` +
        `informada de ${rentabilidade}. Recomendamos avaliar riscos, ` +
        `liquidez e horizonte de investimento.`
      : `não identificamos uma opção elegível pelo critério de saldo ` +
        `mínimo. Podemos avaliar outras possibilidades.`)
  ];

  // 9. Seleciona a mensagem conforme o perfil
  const perfilNormalizado = perfil.toLowerCase();

  let indiceMensagem = 0;

  if (perfilNormalizado === "moderado") {
    indiceMensagem = 1;
  } else if (perfilNormalizado === "arrojado") {
    indiceMensagem = 2;
  }

  // 10. Retorna os dados do cliente
  return {
    nome,
    email: cliente.email ?? "",
    perfil,
    saldo_texto: cliente.saldo ?? "",
    saldo_num: saldoNum,

    recomendacao: investimento
      ? {
          perfil: investimento.perfil,
          produto: investimento.produto,
          minimo: Number(investimento.minimo),
          rentabilidade: investimento.rentabilidade
        }
      : null,

    motivo,

    mensagens: {
      0: mensagens[0],
      1: mensagens[1],
      2: mensagens[2]
    },

    mensagem_escolhida: mensagens[indiceMensagem]
  };
});

// 11. Monta a saída final
const ok =
  clientes.length > 0 &&
  resultados.length === clientes.length &&
  resultados.every(r => r.motivo === "saldo_ok");

return [
  {
    json: {
      ok,
      total_clientes: clientes.length,
      total_investimentos: investimentos.length,
      resultados
    }
  }
];

const resultados = $json.resultados || [];

function parseBRL(valor) {
  if (!valor) return 0;
  const s = String(valor)
    .replace("R$", "")
    .replace(/\./g, "")
    .replace(",", ".")
    .replace(/[^\d.]/g, "")
    .trim();
  const n = Number(s)
  return Number.isFinite(n) ? n : 0;
}

// retorna UM ITEM por cliente
const out = resultados.map(c => {
  const saldoNum = c.saldo_num ?? parseBRL(c.saldo_texto ?? c.saldo);

  return {
    json: {
      email_to: String(c.email || "").trim(),
      nome: String(c.nome || "").trim(),
      perfil: c.perfil,
      saldo_texto: c.saldo_texto ?? c.saldo,
      saldo_num: saldoNum,
      recomendacao: c.recomendacao,
      motivo: c.motivo,
      mensagem_base: c.mensagem_escolhida || c.mensagem || "",
      copy_ruyles: {
        idioma: "pt-BR",
        tom: "amigável e profissional",
        tamanho: "curto (4-6 linhas)",
        evitar: ["promessas de ganho", "garantias", "linguagem agressiva"]
      }
    }
  }
})

return out

