const items = $input.all();
const resultados = [];

function extrairTextos(dado) {
  // A resposta já está normalizada
  if (
    dado.subject !== undefined ||
    dado.text_body !== undefined ||
    dado.html_body !== undefined
  ) {
    return [dado];
  }

  const output = dado.output;

  if (Array.isArray(output)) {
    return output.flatMap(extrairTextos);
  }

  if (output && typeof output === "object") {
    return extrairTextos(output);
  }

  if (Array.isArray(dado.content)) {
    return dado.content
      .filter(c => c.type === "output_text" && c.text)
      .map(c => c.text);
  }

  if (typeof dado.text === "string") {
    return [dado.text];
  }

  return [];
}

for (const item of items) {
  const textos = extrairTextos(item.json);

  for (const texto of textos) {
    try {
      let conteudo;

      if (typeof texto === "string") {
        conteudo = texto
          .trim()
          .replace(/^```(?:json)?\s*/i, "")
          .replace(/\s*```$/, "");

        conteudo = JSON.parse(conteudo);
      } else {
        conteudo = texto;
      }

      resultados.push({
        json: {
          email: conteudo.email ?? "",
          subject: conteudo.subject ?? "",
          text_body: conteudo.text_body ?? "",
          html_body: conteudo.html_body ?? ""
        }
      });

    } catch (erro) {
      resultados.push({
        json: {
          erro: "Não foi possível converter a resposta em JSON.",
          detalhe: erro.message,
          texto_original: texto
        }
      });
    }
  }
}

return resultados;
